function Get-HyperVName {
    [CmdletBinding()]
    param ()
    if ($env:SystemDrive -eq 'X:'){
        Write-host "Unable to get HyperV Name in WinPE"
    }
    else{
        if (((Get-CimInstance Win32_ComputerSystem).Model -eq "Virtual Machine") -and ((Get-CimInstance Win32_ComputerSystem).Manufacturer -eq "Microsoft Corporation")){
            $HyperVName = Get-ItemPropertyValue -Path 'HKLM:\SOFTWARE\Microsoft\Virtual Machine\Guest\Parameters' -Name "VirtualMachineName" -ErrorAction SilentlyContinue
        }
        return $HyperVName
    }
}
function Set-HyperVName {
    [CmdletBinding()]
    param ()
    $HyperVName = Get-HyperVName
    Write-Output "Renaming Computer to $HyperVName"
    Rename-Computer -NewName $HyperVName -Force 
}

try {Set-HyperVName}
catch{}

function Build-ComputerName {
    [CmdletBinding()]
    param(
        [switch]$Apply
    )

    $ComputerSystem = Get-CimInstance -ClassName Win32_ComputerSystem
    $ComputerSystemProduct = Get-CimInstance -ClassName Win32_ComputerSystemProduct
    $Manufacturer = $ComputerSystem.Manufacturer
    $Model = $ComputerSystem.Model
    $CompanyName = "2Pint"
    $Serial = (Get-CimInstance -ClassName win32_bios).SerialNumber
    
    if ($Manufacturer -match "Lenovo"){
        $Model = (($ComputerSystemProduct).Version).split(" ")[1]
        
        $MachineType =  $ComputerSystemProduct.Name.Substring(0, 4)
        $ComputerName = "L$($Model)-$($MachineType)-$($Serial)"
        if ($ComputerName.Length -ge 15){
            $ComputerName = $ComputerName.Substring(0,15)
        }
    }
    elseif (($Manufacturer -match "HP") -or ($Manufacturer -match "Hew")){
        $Manufacturer = "HP"
        $Generation = $Model.split(" ") | Where-Object {$_ -match "G"}
        $Extra = $Model.split(" ") | Where-Object {$_ -like "(*)"}
        if ($Extra){$Model = $Model.replace("$Extra","")}
        if ($Model-match " DM"){$Model = $Model.replace(" DM","")}
        if ($Model-match " Desktop PC"){$Model = $Model.replace(" Desktop PC","")}
        if ($Model-match " Notebook PC"){$Model = $Model.replace(" Notebook PC","")}
        if ($Model-match " Desktop Mini PC"){$Model = $Model.replace(" Desktop Mini PC","")}
        if ($Model-match " Desktop Mini"){$Model = $Model.replace(" Desktop Mini","")}
        if ($Model-match "EliteDesk"){$Model = $Model.replace("EliteDesk","ED")}
        elseif($Model-match "EliteBook"){$Model = $Model.replace("EliteBook","EB")}
        elseif($Model-match "Elite Mini"){$Model = $Model.replace("Elite Mini","EM")}
        elseif($Model-match "Elite x360"){
            $Model = $Model.replace("Elite x360","EBX")
            $Size = $Model.Split(" ")[2]
            $Model = "$($Model.Substring(0,7))$($Size) $($Generation)"
        }
        elseif($Model-match "ProDesk"){$Model = $Model.replace("ProDesk","PD")}
        elseif($Model-match "ProBook"){$Model = $Model.replace("ProBook","PB")}
        elseif($Model-match "ZBook"){$Model = $Model.replace("ZBook","ZB")}
        if ($Model -match "inch"){
            $Split = ($Model.Split('inch')[0])
            $inch = $Split.TrimEnd().Split(" ") | Select-Object -Last 1
            $Model = $Model.replace("$inch inch","")
        }
        if($Model-match "Fury"){$Model = "$($Model.Substring(0,11))$Generation"}
        $Model = $model.replace(" ","")
        if ($Model.Length -gt 15){$ComputerName = $Model.Substring(0,15)}
        else {$ComputerName = $Model}
        if ($ComputerName.Length -lt 15){
            [int]$Extra = 15 - $ComputerName.Length -1
            $LastXofSerial = $Serial.Substring($Serial.Length - $Extra, $Extra)
            $ComputerName = "$($ComputerName)-$($LastXofSerial)"
        }
    }
    elseif($Manufacturer -match "Dell"){
        $Manufacturer = "Dell"
        $Model = (Get-WmiObject -Class:Win32_ComputerSystem).Model
        $ModelNumber = $Model -replace "[^0-9]" , ''
        if ($Model-match "Latitude"){$Model = "DL-$($ModelNumber)"}#{$Model = $Model.replace("Latitude","L")}
        elseif($Model-match "OptiPlex"){$Model = "DO-$($ModelNumber)"}#{$Model = $Model.replace("OptiPlex","O")}
        elseif($Model-match "Precision"){$Model = "DP-$($ModelNumber)"}#{$Model = $Model.replace("Precision","P")}
        $Model = $model.replace(" ","-")
        $ComputerName = "$($Model)-$($Serial)"
    }
    elseif ($Manufacturer -match "Microsoft"){
        if ($Model -match "Virtual"){
            $Random = Get-Random -Maximum 99999
            $ComputerName = "VM-$($CompanyName)-$($Random )"
            if ($ComputerName.Length -gt 15){
                $ComputerName = $ComputerName.Substring(0,15)
            }
        }
    }
    elseif ($Manufacturer -match "Intel"){
        
        $ComputerName = "$($Model)-$($Serial)"
        $ComputerName = $ComputerName.Substring(0,15)
    }
    elseif ($Manufacturer -match "Panasonic"){
        $Model = $Model.Replace("-","")
        $PreFix = "P$($Model)-"
        $SuffixLenght = 15 - $PreFix.Length
        #Get Serial Number, but truncate it to the last $SuffixLenght characters
        if ($Serial.Length -gt $SuffixLenght){
            $Serial = $Serial.Substring($Serial.Length - $SuffixLenght, $SuffixLenght)
        }
        else {
            $Serial = $Serial.PadLeft($SuffixLenght, '0')
        }
        $ComputerName = "$($PreFix)$($Serial)"
        if ($ComputerName.Length -gt 15){
            $ComputerName = $ComputerName.Substring(0,15)
        }
    }
    else {
        if ($Serial.Length -ge 15){
            $ComputerName = $Serial.substring(0,15)
        }
        else{
            $ComputerName = $Serial 
        }
    }
    if ($ComputerName.Length -gt 15){
        Write-Output "-------------------------------------------------------------------------------------------------------------------------------"
        Write-Output "Computer Name is too long, can only be 15 characters."
        Write-Output "Current Computer name is set to: $ComputerName, trimming to....."
        $ComputerName = $ComputerName.Substring(0,15)
        Write-Output "New Name = $ComputerName"
        Write-Output "Your LOGIC Failed, you need to see why it was coming up longer than 15, so you can fix it, instead of having it use the bandaid"
        Write-Output "-------------------------------------------------------------------------------------------------------------------------------"
    }
    if ($Apply){
        rename-computer -NewName $ComputerName -Force -Verbose
    }
    return $ComputerName
}



try {Build-ComputerName -Apply}
catch{}

function enable-privilege {
    param(
    ## The privilege to adjust. This set is taken from
    ## http://msdn.microsoft.com/en-us/library/bb530716(VS.85).aspx
    [ValidateSet(
    "SeAssignPrimaryTokenPrivilege", "SeAuditPrivilege", "SeBackupPrivilege",
    "SeChangeNotifyPrivilege", "SeCreateGlobalPrivilege", "SeCreatePagefilePrivilege",
    "SeCreatePermanentPrivilege", "SeCreateSymbolicLinkPrivilege", "SeCreateTokenPrivilege",
    "SeDebugPrivilege", "SeEnableDelegationPrivilege", "SeImpersonatePrivilege", "SeIncreaseBasePriorityPrivilege",
    "SeIncreaseQuotaPrivilege", "SeIncreaseWorkingSetPrivilege", "SeLoadDriverPrivilege",
    "SeLockMemoryPrivilege", "SeMachineAccountPrivilege", "SeManageVolumePrivilege",
    "SeProfileSingleProcessPrivilege", "SeRelabelPrivilege", "SeRemoteShutdownPrivilege",
    "SeRestorePrivilege", "SeSecurityPrivilege", "SeShutdownPrivilege", "SeSyncAgentPrivilege",
    "SeSystemEnvironmentPrivilege", "SeSystemProfilePrivilege", "SeSystemtimePrivilege",
    "SeTakeOwnershipPrivilege", "SeTcbPrivilege", "SeTimeZonePrivilege", "SeTrustedCredManAccessPrivilege",
    "SeUndockPrivilege", "SeUnsolicitedInputPrivilege")]
    $Privilege,
    ## The process on which to adjust the privilege. Defaults to the current process.
    $ProcessId = $pid,
    ## Switch to disable the privilege, rather than enable it.
    [Switch] $Disable
    )
    
    ## Taken from P/Invoke.NET with minor adjustments.
    $definition = @'
 using System;
 using System.Runtime.InteropServices;
  
 public class AdjPriv
 {
  [DllImport("advapi32.dll", ExactSpelling = true, SetLastError = true)]
  internal static extern bool AdjustTokenPrivileges(IntPtr htok, bool disall,
   ref TokPriv1Luid newst, int len, IntPtr prev, IntPtr relen);
  
  [DllImport("advapi32.dll", ExactSpelling = true, SetLastError = true)]
  internal static extern bool OpenProcessToken(IntPtr h, int acc, ref IntPtr phtok);
  [DllImport("advapi32.dll", SetLastError = true)]
  internal static extern bool LookupPrivilegeValue(string host, string name, ref long pluid);
  [StructLayout(LayoutKind.Sequential, Pack = 1)]
  internal struct TokPriv1Luid
  {
   public int Count;
   public long Luid;
   public int Attr;
  }
  
  internal const int SE_PRIVILEGE_ENABLED = 0x00000002;
  internal const int SE_PRIVILEGE_DISABLED = 0x00000000;
  internal const int TOKEN_QUERY = 0x00000008;
  internal const int TOKEN_ADJUST_PRIVILEGES = 0x00000020;
  public static bool EnablePrivilege(long processHandle, string privilege, bool disable)
  {
   bool retVal;
   TokPriv1Luid tp;
   IntPtr hproc = new IntPtr(processHandle);
   IntPtr htok = IntPtr.Zero;
   retVal = OpenProcessToken(hproc, TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, ref htok);
   tp.Count = 1;
   tp.Luid = 0;
   if(disable)
   {
    tp.Attr = SE_PRIVILEGE_DISABLED;
   }
   else
   {
    tp.Attr = SE_PRIVILEGE_ENABLED;
   }
   retVal = LookupPrivilegeValue(null, privilege, ref tp.Luid);
   retVal = AdjustTokenPrivileges(htok, false, ref tp, 0, IntPtr.Zero, IntPtr.Zero);
   return retVal;
  }
 }
'@
        
    $processHandle = (Get-Process -id $ProcessId).Handle
    $type = Add-Type $definition -PassThru
    $type[0]::EnablePrivilege($processHandle, $Privilege, $Disable)
}
Function Set-ThisPCIconName {
    
    ##*=============================================
    ##* FUNCTION LISTINGS
    ##*=============================================
    #region FunctionListings
    

    
    #endregion
    ##*=============================================
    ##* END FUNCTION LISTINGS
    ##*=============================================
    
    ##*=============================================
    ##* SCRIPT BODY
    ##*=============================================
    #region ScriptBody
    
    #Take OwnerShip
    try {enable-privilege SeTakeOwnershipPrivilege}
    catch{}
    $key = [Microsoft.Win32.Registry]::ClassesRoot.OpenSubKey("CLSID\{20D04FE0-3AEA-1069-A2D8-08002B30309D}",[Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,[System.Security.AccessControl.RegistryRights]::takeownership)
    # You must get a blank acl for the key b/c you do not currently have access
    $acl = $key.GetAccessControl([System.Security.AccessControl.AccessControlSections]::None)
    $identity = "BUILTIN\Administrators"
    $me = [System.Security.Principal.NTAccount]$identity
    $acl.SetOwner($me)
    $key.SetAccessControl($acl)
    
    # After you have set owner you need to get the acl with the perms so you can modify it.
    $acl = $key.GetAccessControl()
    $rule = New-Object System.Security.AccessControl.RegistryAccessRule ($identity,"FullControl","Allow")
    $acl.SetAccessRule($rule)
    $key.SetAccessControl($acl)
    
    $key.Close()
    
    
    #Grant Rights to Admin & System
    # Set Adminstrators of Full Control of Registry Item
    $RegistryPath = "Registry::HKEY_CLASSES_ROOT\CLSID\{20D04FE0-3AEA-1069-A2D8-08002B30309D}"
    
    $identity = "BUILTIN\Administrators"
    $RegistrySystemRights = "FullControl"
    $type = "Allow"
    # Create new rule
    $RegistrySystemAccessRuleArgumentList = $identity, $RegistrySystemRights, $type
    $RegistrySystemAccessRule = New-Object -TypeName System.Security.AccessControl.RegistryAccessRule -ArgumentList $RegistrySystemAccessRuleArgumentList
    # Apply new rule
    $NewAcl = get-acl -Path $RegistryPath
    $NewAcl.SetAccessRule($RegistrySystemAccessRule)
    Set-Acl -Path $RegistryPath -AclObject $NewAcl
    
    
    # Set SYSTEM to Full Control of Registry Item
    $identity = "NT AUTHORITY\SYSTEM"
    $RegistrySystemRights = "FullControl"
    $type = "Allow"
    # Create new rule
    $RegistrySystemAccessRuleArgumentList = $identity, $RegistrySystemRights, $type
    $RegistrySystemAccessRule = New-Object -TypeName System.Security.AccessControl.RegistryAccessRule -ArgumentList $RegistrySystemAccessRuleArgumentList
    # Apply new rule
    $NewAcl.SetAccessRule($RegistrySystemAccessRule)
    Set-Acl -Path $RegistryPath -AclObject $NewAcl
    
    
    #Set the Values to actually make this work
    Set-Item -Path $RegistryPath -Value $env:COMPUTERNAME -Force
    Set-ItemProperty -Path $RegistryPath -Name "LocalizedString" -Value  $env:COMPUTERNAME -Force
    
    #Enable the "This PC" Icon to show on Desktop
    Set-ItemProperty -Path "HKLM:Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel" -Name "{20D04FE0-3AEA-1069-A2D8-08002B30309D}" -Value 0 -Force
    
    #Write Out the Value of the Key
    Get-Item -Path $RegistryPath
    
    #endregion
    ##*=============================================
    ##* END SCRIPT BODY
    ##*=============================================
}
try {Set-ThisPCIconName}
catch{}
